function cloneData(v){return JSON.parse(JSON.stringify(v))}
let SNAPSHOT_ASSETS=cloneData(assets);
const REBALANCER_STORAGE_KEY="30gogo.rebalancer.v1",QQQ_REBALANCE_STORAGE_KEY="30gogo.qqqMonthlyRebalance.v1",LADDER_DROPS=[10,20,35,50,65,80,90,95,97,99];
function defaultSelectedTicker(){return (SNAPSHOT_ASSETS.find(a=>a.theme!=="Cash")||SNAPSHOT_ASSETS[0]).ticker}
function assetSignature(list=SNAPSHOT_ASSETS){return list.map(a=>`${a.ticker}:${a.quantity}:${Math.round(a.value)}:${Math.round(a.cost)}:${Math.round(a.profit)}`).join("|")}
let DASHBOARD_ASSET_SIGNATURE=assetSignature(SNAPSHOT_ASSETS);
function defaultRebalancerState(){return{selectedTicker:defaultSelectedTicker(),targetRatios:{},manualPrices:{},ladderBase:{},ladderQty:{},history:[],portfolio:null,assetSignature:DASHBOARD_ASSET_SIGNATURE,quoteStatus:"가격 조회 대기"}}
function loadRebalancerState(){const base=defaultRebalancerState();try{const raw=localStorage.getItem(REBALANCER_STORAGE_KEY);if(!raw)return base;const saved=JSON.parse(raw)||{};const sameSnapshot=saved.assetSignature===DASHBOARD_ASSET_SIGNATURE;return{...base,...saved,assetSignature:sameSnapshot?saved.assetSignature:DASHBOARD_ASSET_SIGNATURE,targetRatios:{...base.targetRatios,...(saved.targetRatios||{})},manualPrices:sameSnapshot?{...base.manualPrices,...(saved.manualPrices||{})}:base.manualPrices,ladderBase:{...base.ladderBase,...(saved.ladderBase||{})},ladderQty:{...base.ladderQty,...(saved.ladderQty||{})},history:Array.isArray(saved.history)?saved.history.slice(-100):[],portfolio:sameSnapshot&&Array.isArray(saved.portfolio)?saved.portfolio:null}}catch(e){return base}}
function mergeSavedPortfolio(saved){if(!Array.isArray(saved))return cloneData(SNAPSHOT_ASSETS);const byTicker=new Map(saved.map(a=>[a.ticker,a]));return SNAPSHOT_ASSETS.map(s=>{const savedAsset=byTicker.get(s.ticker);if(!savedAsset)return cloneData(s);const next={...cloneData(s)};["quantity","value","cost","profit"].forEach(k=>{if(savedAsset[k]!=null&&!Number.isNaN(Number(savedAsset[k])))next[k]=Number(savedAsset[k])});return next})}
let rebalancerState=loadRebalancerState();if(rebalancerState.portfolio)assets=mergeSavedPortfolio(rebalancerState.portfolio);
let investableAssets,total,totalCost,totalProfit,remaining,progress;
function getCashAsset(){return assets.find(a=>a.theme==="Cash")||assets[0]}
function getAssetByTicker(ticker){return assets.find(a=>a.ticker===ticker)}
function getGuruRow(ticker){return guruData?.rows?.find(r=>r.ticker===ticker)}
function getAllocationAsset(ticker){return getAssetByTicker(ticker)||ALLOCATION_VIRTUAL_ASSETS[ticker]}
function getSnapshotAsset(ticker){return SNAPSHOT_ASSETS.find(a=>a.ticker===ticker)}
function getKrwPrice(a){if(!a||a.theme==="Cash")return 1;const manual=Number(rebalancerState?.manualPrices?.[a.ticker]);if(manual>0)return manual;return Number(a.quantity)>0?Number(a.value||0)/Number(a.quantity):0}
function recalcPortfolio(){const manualPrices=rebalancerState?.manualPrices||{};assets.forEach(a=>{a.quantity=Number(a.quantity)||0;a.value=Number(a.value)||0;a.cost=Number(a.cost)||0;if(a.theme==="Cash"){a.value=Math.max(0,a.value);a.quantity=a.value;a.cost=a.value;a.profit=0}else{const manual=Number(manualPrices[a.ticker]);if(manual>0)a.value=a.quantity*manual;if(a.cost==null&&a.profit!=null)a.cost=a.value-a.profit;if(a.profit==null)a.profit=a.value-a.cost;a.profit=a.value-a.cost}a.returnRate=a.cost>0?a.profit/a.cost:0;a.category=a.theme});investableAssets=assets.filter(a=>a.theme!=="Cash");total=assets.reduce((s,a)=>s+a.value,0);totalCost=assets.reduce((s,a)=>s+a.cost,0);totalProfit=assets.reduce((s,a)=>s+a.profit,0);remaining=TARGET-total;progress=total/TARGET;assets.forEach(a=>a.weight=total?a.value/total:0)}
function saveRebalancerState(){try{rebalancerState.portfolio=cloneData(assets);rebalancerState.assetSignature=assetSignature(assets);localStorage.setItem(REBALANCER_STORAGE_KEY,JSON.stringify(rebalancerState))}catch(e){}}
recalcPortfolio();
const fmt=new Intl.NumberFormat("ko-KR"),won=n=>fmt.format(Math.round(n))+"원",man=n=>fmt.format(Math.round(n/10000))+"만 원",uk=n=>n>=100000000?(Math.round(n/10000000)/10)+"억 원":man(n),pct=n=>(n*100).toFixed(n*100>=10?1:2)+"%";
function yearsToTarget(monthly,annual,current=total,target=TARGET){let bal=current,y=0,mr=Math.pow(1+annual,1/12)-1;while(bal<target&&y<80){for(let m=0;m<12;m++){bal=bal*(1+mr)+monthly;if(bal>=target)break}y++}return y}
function futureValue(years,monthly,annual,current=total){let bal=current,mr=Math.pow(1+annual,1/12)-1;for(let m=0;m<years*12;m++)bal=bal*(1+mr)+monthly;return bal}
function riskScore(){const top=Math.max(...assets.map(a=>a.weight)),growth=assets.filter(a=>a.theme==="Growth 자산").reduce((s,a)=>s+a.value,0)/(total||1),cash=(assets.find(a=>a.theme==="Cash")?.weight||0);return Math.min(100,Math.round(top*60+growth*50+(cash<.05?12:0)+10))}
function animateNumber(el,to,formatter=won){let start=0,dur=900,t0;function step(ts){if(!t0)t0=ts;let p=Math.min(1,(ts-t0)/dur),e=1-Math.pow(1-p,3);el.textContent=formatter(start+(to-start)*e);if(p<1)requestAnimationFrame(step)}requestAnimationFrame(step)}
function makeChart(id,cfg){if(window.charts?.[id])window.charts[id].destroy();window.charts=window.charts||{};if(window.Chart)window.charts[id]=new Chart(document.getElementById(id),cfg)}
const portfolioLabelPlugin={id:"portfolioLabelPlugin",afterDatasetsDraw(chart,args,opts){if(!opts?.enabled)return;const{ctx}=chart,meta=chart.getDatasetMeta(0),values=chart.data.datasets[0]?.data||[],sum=opts.total||values.reduce((s,v)=>s+Math.abs(Number(v)||0),0);ctx.save();ctx.font=opts.font||"900 11px Inter, system-ui, sans-serif";ctx.textAlign="center";ctx.textBaseline="middle";values.forEach((raw,i)=>{const value=Number(raw)||0,el=meta.data[i];if(!el||!value)return;const share=sum?Math.abs(value)/sum:0;if(opts.minShare&&share<opts.minShare)return;let pos=el.tooltipPosition(),x=pos.x,y=pos.y,label=opts.format==="profit"?`${value>=0?"+":""}${uk(value)}`:opts.format==="percent"?pct(share):`${uk(value)} · ${pct(share)}`;if(opts.placement==="bar"){const props=el.getProps(["x","y","base"],true);x=props.x;y=value>=0?props.y-13:props.y+13;ctx.textBaseline=value>=0?"bottom":"top"}ctx.lineWidth=4;ctx.strokeStyle="rgba(5,7,13,.82)";ctx.strokeText(label,x,y);ctx.fillStyle=opts.color||"#f7f9ff";ctx.fillText(label,x,y)});ctx.restore()}};
