function applyRuntimeMode(){const local=isLocalRuntime();document.body.classList.toggle("local-runtime",local);document.body.classList.toggle("pages-runtime",!local);const note=document.getElementById("runtimeNote");if(note)note.textContent=local?"Mac 로컬 실행 화면입니다. 주문 기능은 별도 잠금 해제 후에만 열립니다.":"암호화 스냅샷 조회 화면입니다. 주문과 증권사 연결 기능은 포함되지 않습니다."}
