function fmtRatioValue(n){return Number.isInteger(n)?String(n):n.toFixed(2).replace(/0+$/,"").replace(/\.$/,"")}
function selectedAsset(){let a=getAssetByTicker(rebalancerState.selectedTicker);if(!a||a.theme==="Cash"){a=investableAssets[0];rebalancerState.selectedTicker=a?.ticker||defaultSelectedTicker()}return a}
function selectedTargetRatio(){const ticker=selectedAsset()?.ticker;const v=Number(rebalancerState.targetRatios[ticker]);return v>0?v:1}
