function usdKrwRateFor(a){const row=getGuruRow(a.ticker),snap=getSnapshotAsset(a.ticker);if(row?.price&&snap?.quantity&&snap?.value)return snap.value/(snap.quantity*row.price);return 1350}
function auxiliaryPriceNote(a){const row=getGuruRow(a.ticker);if(dashboardConfig.manualQuoteExcluded.includes(a.ticker))return"자동조회 제외 자산: 암호화 스냅샷 또는 수동값으로 관리합니다.";if(row?.currency==="USD"&&row.price)return`보조 달러 현재가 ${"$"+Number(row.price).toLocaleString("en-US",{maximumFractionDigits:2})}, 환산 기준 약 ${fmt.format(Math.round(usdKrwRateFor(a)))}원/USD`;if(row?.currency==="KRW"&&row.price)return`국내 가격 스냅샷 ${fmt.format(Math.round(row.price))}원`;return"외부 가격 조회 실패 시 현재 스냅샷 또는 수동 입력값을 사용합니다."}
function escapeHtml(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function recordRebalanceEvent(type,ticker,amount,detail){const a=getAssetByTicker(ticker)||selectedAsset(),cash=getCashAsset(),event={type,ticker:a?.ticker||ticker,name:a?.name||ticker,amount:Number(amount)||0,detail:detail||"",time:new Date().toLocaleString("ko-KR",{hour12:false}),assetValue:a?.value||0,cashValue:cash?.value||0,totalValue:total||0,quantity:a?.quantity||0,price:a?getKrwPrice(a):0};rebalancerState.history=[event,...(rebalancerState.history||[])].slice(0,100)}
