function changeCash(direction){const amount=Math.max(0,numInput("rebCashAmount"));if(!amount)return alert("금액을 입력하세요.");const cash=getCashAsset(),next=cash.value+direction*amount;if(next<0)return alert("현금이 부족합니다.");setCashValue(next);recordRebalanceEvent(direction>0?"deposit":"withdraw",selectedAsset().ticker,direction*amount,direction>0?"입금":"출금");document.getElementById("rebCashAmount").value="";persistAndRender()}
function executeTrade(side){const a=selectedAsset(),qty=Math.max(0,numInput("rebTradeQty")),price=numInput("rebTradePrice")||getKrwPrice(a),feeRate=numInput("rebFeeRate")/100,feeFixed=numInput("rebFeeFixed"),cash=getCashAsset();if(!qty||!price)return alert("수량과 체결가를 확인하세요.");const gross=qty*price,fee=Math.round(gross*feeRate+feeFixed);if(side==="buy"){const totalCostTrade=gross+fee;if(totalCostTrade>cash.value)return alert("공통 현금풀이 부족합니다.");a.cost+=totalCostTrade;a.quantity+=qty;a.value=a.quantity*price;rebalancerState.manualPrices[a.ticker]=price;setCashValue(cash.value-totalCostTrade);recordRebalanceEvent("buy",a.ticker,-totalCostTrade,`${fmtQty(qty)} 매수 · ${fmtPrice(price)} · 수수료 ${money(fee)}`)}else{if(qty>a.quantity)return alert("보유 수량을 초과할 수 없습니다.");const beforeQty=a.quantity,proceeds=Math.max(0,gross-fee),costOut=beforeQty>0?a.cost*(qty/beforeQty):0;a.quantity-=qty;a.cost=Math.max(0,a.cost-costOut);a.value=a.quantity*price;rebalancerState.manualPrices[a.ticker]=price;setCashValue(cash.value+proceeds);recordRebalanceEvent("sell",a.ticker,proceeds,`${fmtQty(qty)} 매도 · ${fmtPrice(price)} · 수수료 ${money(fee)}`)}document.getElementById("rebTradeQty").value="";document.getElementById("rebTradePrice").value="";persistAndRender()}
