function ladderQtyFor(a,drop,price,cash){const stored=rebalancerState.ladderQty?.[a.ticker]?.[drop];if(stored!=null)return Number(stored)||0;const weight=drop<30?.07:drop<65?.1:drop<90?.14:.18;return price>0?Math.floor((cash*weight)/price):0}
