function renderRebalanceAction(a){const ratio=selectedTargetRatio(),price=getKrwPrice(a),cash=getCashAsset().value,stockValue=a.value,pool=stockValue+cash,targetStock=pool*(ratio/(ratio+1)),delta=targetStock-stockValue,threshold=pool*.01,qty=price>0?Math.abs(delta)/price:0;document.getElementById("rebTargetRatio").textContent=`${fmtRatioValue(ratio)} : 1`;if(Math.abs(delta)<=threshold){rebActionTitle.textContent="주식:현금 균형 유지";rebActionDetail.textContent=`현재 ${a.name} 비중은 목표 범위 안입니다. 매도·매수 불필요.`;rebActionNote.textContent=`목표 주식 ${compactMoney(targetStock)} · 현재 주식 ${compactMoney(stockValue)}`;return}if(delta>0){rebActionTitle.textContent=`${a.name} ${compactMoney(delta)} 매수 필요`;rebActionDetail.textContent=`목표 비율 ${fmtRatioValue(ratio)}:1 기준으로 약 ${fmtQty(qty)}를 추가 매수하면 균형에 가까워집니다.`}else{rebActionTitle.textContent=`${a.name} ${compactMoney(Math.abs(delta))} 매도 필요`;rebActionDetail.textContent=`목표 비율 ${fmtRatioValue(ratio)}:1 기준으로 약 ${fmtQty(qty)}를 줄이면 현금 비중이 회복됩니다.`}rebActionNote.textContent=`현재 주식 ${compactMoney(stockValue)} · 현금 ${compactMoney(cash)} · 목표 주식 ${compactMoney(targetStock)}`}
function renderLadder(a){const tbody=document.getElementById("rebLadderRows"),price=getKrwPrice(a),cash=getCashAsset().value,avg=a.quantity>0?a.cost/a.quantity:price,base=Number(rebalancerState.ladderBase[a.ticker])||avg;document.getElementById("rebBasePrice").value=Math.round(base);document.getElementById("rebCurrentReadonly").value=fmtPrice(price);let cumulative=0;tbody.innerHTML=LADDER_DROPS.map(drop=>{const rowPrice=base*(1-drop/100),qty=ladderQtyFor(a,drop,rowPrice,cash),amount=rowPrice*qty;cumulative+=amount;const ok=cumulative<=cash;return`<tr><td>${drop}%</td><td>${fmtPrice(rowPrice)}</td><td><input class="reb-input" type="number" min="0" step="0.000001" value="${qty}" data-ladder-drop="${drop}"></td><td><span class="reb-status ${ok?"":"bad"}">${ok?"대기":"실탄부족"}</span></td><td>${money(cumulative)}</td></tr>`}).join("")}
