async function refreshQuoteForSelected(showAlert=true){
  const a=selectedAsset();
  if(!a||dashboardConfig.manualQuoteExcluded.includes(a.ticker)){rebalancerState.quoteStatus="자동조회 제외 · 수동 관리";renderRebalancer();return}
  if(!isLocalRuntime()){rebalancerState.quoteStatus="Pages 조회 전용 · 시간별 스냅샷 사용";renderRebalancer();return}
  rebalancerState.quoteStatus=`${a.ticker} 조회 중`;renderRebalancer();
  try{
    const res=await fetch(`/__local/quote?symbol=${encodeURIComponent(a.ticker)}`,{cache:"no-store"});
    const quote=await res.json();
    if(!res.ok||!(Number(quote.priceKrw)>0))throw new Error("가격 없음");
    rebalancerState.manualPrices[a.ticker]=Number(quote.priceKrw);a.value=a.quantity*Number(quote.priceKrw);
    rebalancerState.quoteStatus=`로컬 현재가 · ${a.ticker}`;recordRebalanceEvent("price",a.ticker,quote.priceKrw,"로컬 서버 현재가");persistAndRender();
  }catch(e){rebalancerState.quoteStatus=`${a.ticker} 조회 실패 · 스냅샷 유지`;if(showAlert)alert("현재가 조회에 실패했습니다. 스냅샷 또는 수동값을 유지합니다.");renderRebalancer()}
}
