async function fetchQqqReferencePrice(){
  const status=document.getElementById("qqqPriceStatus");
  if(!isLocalRuntime()){if(status)status.textContent="Pages에서는 시간별 스냅샷 또는 수동 기준가격을 사용합니다.";return}
  if(status)status.textContent="QQQ 참고가격 조회 중...";
  try{const res=await fetch("/__local/quote?symbol=QQQ",{cache:"no-store"}),quote=await res.json();if(!res.ok||!(Number(quote.priceUsd)>0))throw new Error("가격 없음");document.getElementById("qqqReferencePrice").value=Number(quote.priceUsd).toFixed(2);document.getElementById("qqqPriceTimestamp").value=quote.timestamp||new Date().toISOString();qqqSaveRequest(qqqReadRequest());if(status)status.textContent="로컬 Toss 참고가격을 입력했습니다. 실제 주문 직전에 다시 확인합니다.";qqqClearResult();updateQqqTargetDisplay()}catch(e){if(status)status.textContent="참고가격 조회 실패: 수동 기준가격을 사용하세요."}
}
