function renderKPI(){const y=yearsToTarget(profile.monthly,.10),k=[["총자산",total,uk,"평가금액 자동 합산","◎"],["투자 원금",totalCost,uk,"원금 자동 합산","₩"],["총 평가손익",totalProfit,uk,"평가금액 - 원금","↗"],["손익률",totalCost?totalProfit/totalCost:0,pct,"전체 포트폴리오 기준","%"],["30억까지 남은 금액",remaining,uk,"목표까지의 거리","△"],["목표 달성률",progress,pct,"30억 대비 현재 위치","%"],["예상 FIRE 나이",profile.age+y,v=>Math.round(v)+"세","연 10% · 저장된 월 투자금 기준","F"],["포트폴리오 위험도",riskScore(),v=>Math.round(v)+"/100","집중도와 변동성 반영","!"]];kpiGrid.innerHTML=k.map((x,i)=>`<article class="card kpi"><div class="icon">${x[4]}</div><span class="label">${x[0]}</span><b id="kpi${i}">-</b><small>${x[3]}</small></article>`).join("");k.forEach((x,i)=>animateNumber(document.getElementById("kpi"+i),x[1],x[2]))}
function commandPct(value){return value==null||!Number.isFinite(Number(value))?"-":`${Number(value)>=0?"+":""}${pct(Number(value))}`}
function commandFreshness(){const generated=new Date(dashboardGeneratedAt),age=Number.isNaN(generated.getTime())?Infinity:Date.now()-generated.getTime(),hours=age/3600000;return{age,hours,tone:hours<=2?"green":hours<=6?"gold":"red",label:hours<1?`${Math.max(0,Math.round(age/60000))}분 전`:Number.isFinite(hours)?`${hours.toFixed(hours<10?1:0)}시간 전`:"시각 없음"}}
function commandSeriesForRange(){const series=Array.isArray(performanceData.series)?performanceData.series:[];if(!series.length||commandRange==="ALL")return series;const last=new Date(`${series[series.length-1].date}T00:00:00`),cutoff=new Date(last);if(commandRange==="1M")cutoff.setDate(cutoff.getDate()-30);else if(commandRange==="3M")cutoff.setDate(cutoff.getDate()-90);else if(commandRange==="YTD")cutoff.setMonth(0,1);return series.filter(row=>new Date(`${row.date}T00:00:00`)>=cutoff)}
function renderCommandPerformance(){const series=commandSeriesForRange(),canvas=document.getElementById("commandPerformanceChart"),note=document.getElementById("commandPerformanceNote");if(!canvas)return;if(!series.length){if(window.charts?.commandPerformanceChart)window.charts.commandPerformanceChart.destroy();if(note)note.textContent="성과 이력이 아직 없습니다.";return}const firstPortfolio=Number(series[0].portfolioIndex)||100,firstBenchmark=Number(series[0].benchmarkIndex)||100,portfolio=series.map(row=>(Number(row.portfolioIndex)||firstPortfolio)/firstPortfolio*100),benchmark=series.map(row=>row.benchmarkIndex==null?null:Number(row.benchmarkIndex)/firstBenchmark*100);makeChart("commandPerformanceChart",{type:"line",data:{labels:series.map(row=>row.date.slice(5).replace("-","/")),datasets:[{label:"포트폴리오 TWR",data:portfolio,borderColor:"#35d399",backgroundColor:"rgba(53,211,153,.1)",fill:true,tension:.28,pointRadius:series.length>45?0:1.5,borderWidth:2.4},{label:"QQQ 원화환산",data:benchmark,borderColor:"#f5c86b",backgroundColor:"transparent",tension:.28,pointRadius:series.length>45?0:1.5,borderWidth:2.2,borderDash:[7,5]}]},options:{maintainAspectRatio:false,interaction:{mode:"index",intersect:false},plugins:{legend:{position:"bottom",labels:{color:"#dce7ff",usePointStyle:true,boxWidth:9}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${Number(c.parsed.y).toFixed(2)}`}}},scales:{x:{ticks:{color:"#8f9ab0",maxRotation:0,maxTicksLimit:9},grid:{color:"rgba(255,255,255,.05)"}},y:{ticks:{color:"#8f9ab0",callback:value=>Number(value).toFixed(0)},grid:{color:"rgba(255,255,255,.08)"}}}}});if(note){const status=performanceData.status==="official"?"입출금 원장 확인 완료":"입출금 원장 확인 전 잠정";note.textContent=`${performanceData.officialStart||"2026-06-23"} 시작 · 일별 TWR · ${status} · QQQ는 일봉과 원/달러 스냅샷으로 환산`}}
function commandActionRows(){const rows=[],fresh=commandFreshness(),ranked=[...investableAssets].sort((a,b)=>b.weight-a.weight),top=ranked[0],cash=getCashAsset(),summary=performanceData.summary||{};if(fresh.hours>2)rows.push({tone:fresh.hours>6?"bad":"",title:"데이터 동기화 확인",detail:`마지막 갱신 ${fresh.label}. 1시간 동기화 상태를 확인합니다.`});if(performanceData.status!=="official")rows.push({tone:"bad",title:"입출금 원장 확인",detail:`현재 ${performanceData.reviewedThrough||performanceData.officialStart||"-"}까지 확인됨. 로컬에서 입출금을 보완하고 오늘까지 확인합니다.`});if(top?.weight>.45)rows.push({tone:"bad",title:`${top.name} 집중도 점검`,detail:`현재 비중 ${pct(top.weight)}. 신규 매수 전 집중 한도를 확인합니다.`});if((cash?.weight||0)<.05)rows.push({tone:"bad",title:"현금 완충 보강",detail:`현재 현금 비중 ${pct(cash?.weight||0)}. 급락 대응 여력이 5% 기준보다 낮습니다.`});if(Number(summary.maxDrawdown)<-.1)rows.push({tone:"",title:"낙폭 구간 점검",detail:`공식 구간 최대 낙폭 ${pct(summary.maxDrawdown)}. 투자 논리와 분할 대응 한도를 확인합니다.`});if(!rows.length)rows.push({tone:"good",title:"즉시 조치 없음",detail:"데이터, 현금, 집중도와 원장 상태가 설정한 기준 안에 있습니다."});return rows.slice(0,5)}
function renderCommandActions(){const root=document.getElementById("commandActions"),count=document.getElementById("commandActionCount");if(!root)return;const rows=commandActionRows();root.innerHTML=rows.map(row=>`<div class="command-action ${row.tone}"><i></i><div><b>${escapeHtml(row.title)}</b><span>${escapeHtml(row.detail)}</span></div></div>`).join("");if(count)count.textContent=`${rows.filter(row=>row.tone!=="good").length}건`}
function renderCommandContribution(){const canvas=document.getElementById("commandContributionChart");if(!canvas)return;const rows=(performanceData.contributions||[]).filter(row=>row.ticker!=="CASH").slice(0,8).reverse();if(!rows.length){if(window.charts?.commandContributionChart)window.charts.commandContributionChart.destroy();return}makeChart("commandContributionChart",{type:"bar",data:{labels:rows.map(row=>row.name),datasets:[{label:"가격 변화 기여",data:rows.map(row=>row.amountKrw),backgroundColor:rows.map(row=>row.amountKrw>=0?"rgba(53,211,153,.72)":"rgba(251,113,133,.72)"),borderColor:rows.map(row=>row.amountKrw>=0?"#35d399":"#fb7185"),borderWidth:1,borderRadius:4}]},options:{indexAxis:"y",maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>money(c.parsed.x)}}},scales:{x:{ticks:{color:"#8f9ab0",callback:value=>compactMoney(value)},grid:{color:"rgba(255,255,255,.08)"}},y:{ticks:{color:"#dce7ff"},grid:{display:false}}}}})}
function renderCommandLiquidity(){const root=document.getElementById("commandLiquidity");if(!root)return;const cash=getCashAsset(),ranked=[...investableAssets].sort((a,b)=>b.weight-a.weight).slice(0,5);root.innerHTML=`<div class="command-liquidity-summary"><div><span>공통 현금</span><b>${compactMoney(cash?.value||0)}</b></div><div><span>현금 비중</span><b class="${(cash?.weight||0)<.05?"neg":"pos"}">${pct(cash?.weight||0)}</b></div></div>${ranked.map(a=>`<div class="command-exposure-row"><b>${escapeHtml(a.name)}</b><div class="bar-bg"><div class="bar-fill" style="width:${Math.min(100,a.weight*100)}%;background:${a.color||"#42d7ff"}"></div></div><span>${pct(a.weight)}</span></div>`).join("")}`}
function renderCommandHealth(){const root=document.getElementById("commandDataHealth"),freshness=document.getElementById("commandFreshness"),status=document.getElementById("commandStatus"),summary=performanceData.summary||{},fresh=commandFreshness();if(freshness){freshness.className=`badge ${fresh.tone}`;freshness.textContent=`갱신 ${fresh.label}`}if(status){status.className=`badge ${performanceData.status==="official"?"green":"gold"}`;status.textContent=performanceData.status==="official"?"공식 성과":"잠정 성과"}if(!root)return;const rows=[["스냅샷 최신성",fresh.label,fresh.hours<=2?"정상":"확인"],["공식 성과 시작",performanceData.officialStart||"2026-06-23",`${summary.snapshotDays||0}일`],["입출금 원장",performanceData.reviewedThrough||"미확인",performanceData.status==="official"?"완료":"보완"],["QQQ 원화 벤치마크",performanceData.benchmark?.asOf||"없음",performanceData.benchmark?.asOf?"정상":"확인"]];root.innerHTML=rows.map(row=>`<div class="command-health-row"><div><b>${row[0]}</b><span>${row[1]}</span></div><strong>${row[2]}</strong></div>`).join("")}
