function renderCommandCenter(){if(!document.getElementById("commandCenter"))return;const summary=performanceData.summary||{},kpis=[["현재 순자산",total,compactMoney,"최신 암호화 스냅샷"],[performanceData.status==="official"?"공식 TWR":"잠정 TWR",summary.portfolioReturn,commandPct,`${performanceData.officialStart||"2026-06-23"} 이후`],["QQQ 원화환산",summary.benchmarkReturn,commandPct,"같은 기간 비교"],["초과성과",summary.excessReturn,commandPct,"포트폴리오 - QQQ"],["최대 낙폭",summary.maxDrawdown,commandPct,"TWR 고점 대비"],["외부 순입출금",summary.netExternalFlowKrw,compactMoney,`${summary.cashFlowCount||0}건 반영`]],root=document.getElementById("commandKpis");if(root)root.innerHTML=kpis.map(item=>`<div class="command-kpi"><span>${item[0]}</span><b>${item[2](item[1])}</b><small>${item[3]}</small></div>`).join("");renderCommandPerformance();renderCommandActions();renderCommandContribution();renderCommandLiquidity();renderCommandHealth();renderCommandFlows()}
