  makeChart("profitChart",{type:"bar",data:{labels:assets.map(a=>a.name),datasets:[{data:assets.map(a=>a.profit),backgroundColor:assets.map(a=>a.profit>=0?"rgba(53,211,153,.72)":"rgba(251,113,133,.72)"),borderRadius:12}]},options:{layout:{padding:{top:24,bottom:24}},plugins:{legend:{display:false},portfolioLabelPlugin:{enabled:true,placement:"bar",format:"profit"}},scales:{x:{ticks:{color:"#cbd5e1"},grid:{display:false}},y:{ticks:{color:"#94a3b8",callback:v=>uk(v)},grid:{color:"rgba(255,255,255,.08)"}}}},plugins:[portfolioLabelPlugin]});
  const plan=dashboardConfig.allocationPlan.filter(row=>!row.hold&&row.share>0).map(row=>({...row,asset:getAllocationAsset(row.ticker)})).filter(row=>row.asset);
  makeChart("allocationChart",{type:"doughnut",data:{labels:plan.map(row=>row.asset.name),datasets:[{data:plan.map(row=>row.share),backgroundColor:plan.map(row=>row.asset.color)}]},options:{plugins:{legend:{position:"bottom",labels:{color:"#dce7ff"}},portfolioLabelPlugin:{enabled:true,total:plan.reduce((sum,row)=>sum+row.share,0),format:"percent"}},cutout:"58%"},plugins:[portfolioLabelPlugin]});
  const ranked=[...investableAssets].sort((a,b)=>b.weight-a.weight),first=ranked[0],second=ranked[1];
  if(first)teslaWarn.innerHTML=`<b>1위 집중도 ${pct(first.weight)}</b><br>복호화 종목 기준 상위 보유 비중 감시`;
  if(second)rocketWarn.innerHTML=`<b>2위 집중도 ${pct(second.weight)}</b><br>상위 두 종목 합산 ${pct(first.weight+second.weight)}`;
  portfolioDiagnosis.textContent=`총자산은 ${uk(total)}, 목표 달성률은 ${pct(progress)}입니다. 상위 종목 집중도와 Core·Growth·현금 비중을 함께 관리합니다.`;
