  makeChart("muskChart",{type:"radar",data:{labels:ecosystem.map(x=>x.label),datasets:[{label:"관계 점수",data:ecosystem.map(x=>x.score),borderColor:"#fb7185",backgroundColor:"rgba(251,113,133,.18)",pointBackgroundColor:"#f5c86b"}]},options:{plugins:{legend:{labels:{color:"#dce7ff"}}},scales:{r:{min:0,max:100,ticks:{display:false},grid:{color:"rgba(255,255,255,.12)"},angleLines:{color:"rgba(255,255,255,.12)"},pointLabels:{color:"#dce7ff"}}}}});
  muskNote.innerHTML=ecosystem.length?`<b>암호화 관계 모델</b><br>${ecosystem.map(x=>`${x.label} ${pct(x.value/(total||1))}`).join(" · ")}`:'<b>관계 모델 없음</b>';
  const infra={};assets.filter(a=>a.infra).forEach(a=>infra[a.infra]=(infra[a.infra]||0)+a.value);
  const labels=Object.keys(infra),vals=Object.values(infra),infraTotal=vals.reduce((s,v)=>s+v,0);
  makeChart("aiInfraChart",{type:"doughnut",data:{labels,datasets:[{data:vals,backgroundColor:["#a3e635","#35d399","#22d3ee","#c084fc","#60a5fa"],borderColor:"rgba(255,255,255,.12)",borderWidth:1}]},options:{plugins:{legend:{position:"bottom",labels:{color:"#dce7ff"}},portfolioLabelPlugin:{enabled:true,total:infraTotal,minShare:.02,format:"valuePct"}},cutout:"55%"},plugins:[portfolioLabelPlugin]});
  aiInfraList.innerHTML=labels.map((label,i)=>`<div class="exposure-row"><b>${label}</b><div class="bar-bg"><div class="bar-fill" style="width:${infraTotal?vals[i]/infraTotal*100:0}%;background:linear-gradient(90deg,#42d7ff,#f5c86b)"></div></div><span>${pct(vals[i]/(total||1))}</span></div>`).join("");
