function briefingAction(asset,row){const score=Number(row?.finalScore);if(asset.weight>=.35)return{label:"신규매수 중단",tone:"red",detail:`현재 비중 ${pct(asset.weight)}로 집중 관리가 우선입니다.`};if(Number.isFinite(score)&&score<45)return{label:"추가매수 보류",tone:"red",detail:`구루 종합 ${score}점. 가격보다 사업·수익성 개선을 먼저 확인합니다.`};if(Number.isFinite(score)&&score>=70&&asset.weight<.05)return{label:"관찰 매수 후보",tone:"green",detail:`구루 종합 ${score}점이지만 QQQ·현금 배정 후 잔여 한도에서만 검토합니다.`};if(asset.weight>=.1)return{label:"보유·비중관리",tone:"gold",detail:`현재 비중 ${pct(asset.weight)}. 신규자금보다 기존 포지션 관리가 우선입니다.`};return{label:"보유·관찰",tone:"gold",detail:Number.isFinite(score)?`구루 종합 ${score}점. QQQ 중심 신규자금 원칙과 별도로 관찰합니다.`:"부분 지표이므로 신규매수를 보류하고 데이터 보완을 기다립니다."}}
