  guruCards.innerHTML=[...guruData.rows].sort((a,b)=>b.finalScore-a.finalScore).map(r=>`<article class="guru-card"><div class="theme-row"><span>${r.theme}</span><b class="ticker-chip">${r.ticker}</b></div><h3>${r.name}</h3><div class="guru-score">${r.finalScore}</div><span class="badge guru-signal ${signalTone(r.signal)}">${r.signal}</span><p class="guru-comment">${r.comment}</p><div class="chipline"><span class="chip">Buffett ${r.scores.Buffett}</span><span class="chip">Lynch ${r.scores.Lynch}</span><span class="chip">Innovation ${r.scores.Innovation}</span><span class="chip">Momentum ${r.scores.Momentum}</span></div></article>`).join('');
  const cols={pe:guruData.rows.map(r=>r.metrics?.pe),pb:guruData.rows.map(r=>r.metrics?.pb),ps:guruData.rows.map(r=>r.metrics?.ps),roe:guruData.rows.map(r=>r.metrics?.roe),op:guruData.rows.map(r=>r.metrics?.operatingMargin),fcf:guruData.rows.map(r=>r.metrics?.fcfYield),growth:guruData.rows.map(r=>r.metrics?.revenueGrowth),debt:guruData.rows.map(r=>r.metrics?.debtEquity),pos:guruData.rows.map(r=>{const m=r.metrics||{};return (r.price&&m.high52&&m.low52&&m.high52>m.low52)?((r.price-m.low52)/(m.high52-m.low52)):null;})};
  const stats=k=>cols[k].filter(v=>v!=null&&!Number.isNaN(v));
  valuationTable.innerHTML=guruData.rows.map(r=>{const m=r.metrics||{}, pos=(r.price&&m.high52&&m.low52&&m.high52>m.low52)?((r.price-m.low52)/(m.high52-m.low52)):null;return `<tr><td><div class="asset-name">${r.name}</div><span class="ticker-chip">${r.ticker}</span></td><td><span class="badge ${signalTone(r.signal)}">${r.signal}</span><br><b>${r.finalScore}/100</b></td><td>${metricCell(m.pe,'ratio',stats('pe'))}</td><td>${metricCell(m.pb,'ratio',stats('pb'))}</td><td>${metricCell(m.ps,'ratio',stats('ps'))}</td><td>${metricCell(m.roe,'pct',stats('roe'))}</td><td>${metricCell(m.operatingMargin,'pct',stats('op'))}</td><td>${metricCell(m.fcfYield,'pct',stats('fcf'))}</td><td>${metricCell(m.revenueGrowth,'pct',stats('growth'))}</td><td>${metricCell(m.debtEquity,'ratio',stats('debt'))}</td><td>${pos==null?'<span class="metric-pill metric-na">확인 필요</span>':metricCell(pos,'pct',stats('pos'))}</td><td><span class="metric-muted">${(r.dataStatus==='live'||r.dataStatus==='broker')?'브로커/공개 지표':'부분 지표'}<br>${m.fiscal_period||''}</span></td></tr>`}).join('');
  const legend=document.getElementById('metricLegend');
  if(legend) legend.innerHTML='<span><i style="background:linear-gradient(135deg,rgba(245,200,107,.28),rgba(255,244,214,.96));border:1px solid rgba(245,200,107,.62)"></i> 튀는 값</span><span><i style="background:linear-gradient(135deg,rgba(251,113,133,.25),rgba(255,224,230,.95));border:1px solid rgba(251,113,133,.58)"></i> 음수/이상치</span><span><i style="background:rgba(141,152,173,.16);border:1px solid rgba(141,152,173,.2)"></i> 확인 필요</span>';
